const r = $('HTTP: reporte JSON').item.json.data;
const kpis = Object.fromEntries((r.businessKpis || []).map((k) => [k.name, k.value]));
const metrics = Object.fromEntries((r.modelMetrics || []).map((m) => [m.metric, m.value]));
const summary = [
  `Reporte semanal ${r.window.start.slice(0,10)} → ${r.window.end.slice(0,10)}.`,
  `Órdenes totales: ${r.ordersByStatus.reduce((a, b) => a + b.count, 0)}.`,
  `Paradas evitadas: ${(kpis.downtime_avoided_h ?? 0).toFixed(0)}h.`,
  `Ahorro estimado: €${(kpis.cost_savings_eur ?? 0).toLocaleString('es-ES')}.`,
  `Precisión del modelo: ${((metrics.precision ?? 0) * 100).toFixed(1)}%.`,
  `Disponibilidad: ${((kpis.availability ?? 0) * 100).toFixed(1)}%.`,
].join(' ');
return [{ json: { summary } }];

// Genera sección de alertas destacadas
const r = $('HTTP: reporte JSON').item.json.data;
const metrics = Object.fromEntries((r.modelMetrics || []).map((m) => [m.metric, m.value]));
const alerts = [];
if ((metrics.precision ?? 0) < 0.85) alerts.push(`⚠️ Precisión del modelo ${((metrics.precision ?? 0) * 100).toFixed(1)}% (objetivo 85%)`);
if ((metrics.false_positives ?? 0) > 0.10) alerts.push(`⚠️ Falsos positivos ${((metrics.false_positives ?? 0) * 100).toFixed(1)}% (objetivo ≤ 10%)`);
const top = r.topPredictions?.[0];
if (top && top.maxProb > 0.9) alerts.push(`🔴 Equipo ${top.name} con probabilidad máxima ${(top.maxProb * 100).toFixed(1)}%`);
// Propaga el binario del PDF (viene del nodo FS anterior) para poder adjuntarlo al email.
const binary = $input.first().binary;
return [binary ? { json: { alerts }, binary } : { json: { alerts } }];
